        .heart:nth-child(2) { background-color: rgba(173, 216, 230, 0.8); } /* 水色 */
        .heart:nth-child(3) { background-color: rgba(240, 179, 158, 0.8); } /* 薄い橙 */
        .heart:nth-child(4) { background-color: rgba(138, 43, 226, 0.8); } /* 紫 */


        @keyframes pulse {
            0% { transform: scale(1); }
            100% { transform: scale(1.15); }
        }

        /* マウスオーバー時の効果（タップ時のインタラクションをシミュレート） */
        #heart-container:hover .heart {
            animation: pulse 1s infinite alternate;
        }
    </style>
</head>
<body>

    <div id="heart-container">
        <!-- JavaScriptでハートが生成されます -->
    </div>

    <script>
        const container = document.getElementById('heart-container');
        const numberOfHearts = 4; // 表示するハートの数

        function createHeart() {
            const heart = document.createElement('div');
            heart.classList.add('heart');

            // ランダムな初期位置を設定
            const randomX = Math.random() * (container.offsetWidth - 50);
            const randomY = Math.random() * (container.offsetHeight - 50);

            heart.style.left = `${randomX}px`;
            heart.style.top = `${randomY}px`;

            container.appendChild(heart);
        }

        // タップイベント（クリックイベント）を処理
        container.addEventListener('click', () => {
            // クリックされたときに、すべてのハートにアニメーションを適用
            const hearts = container.querySelectorAll('.heart');
            hearts.forEach(heart => {
                heart.style.animation = 'pulse 1s infinite alternate';
            });
        });

        // 初期ロード時にハートを生成
        for (let i = 0; i < numberOfHearts; i++) {
            createHeart();
        }
    </script>
